var e={source:`https://metallik.ru/articles/`,checkedAt:`2026-10-24`,categories:[{id:`dymokhody`,title:`Дымоходы`,source:`https://metallik.ru/articles/dymokhody/`},{id:`vodostochnaya-sistema`,title:`Водостоки`,source:`https://metallik.ru/articles/vodostochnaya-sistema/`},{id:`krovlya`,title:`Кровля`,source:`https://metallik.ru/articles/krovlya/`},{id:`list-fasadnyy`,title:`Лист фасадный`,source:`https://metallik.ru/articles/list-fasadnyy/`},{id:`komplektuyushchie-i-dobornye-elementy`,title:`Доборные элементы`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/`},{id:`profnastil`,title:`Профнастил`,source:`https://metallik.ru/articles/profnastil/`},{id:`shtaketnik-metallicheskiy`,title:`Штакетник`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/`},{id:`ograzhdeniya-zhalyuzi`,title:`Ограждения жалюзи`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/`},{id:`sayding`,title:`Сайдинг, софиты`,source:`https://metallik.ru/articles/sayding/`},{id:`profil-dlya-gipsokartona`,title:`Профиль для гипсокартона`,source:`https://metallik.ru/articles/profil-dlya-gipsokartona/`},{id:`sbornoe`,title:`Полезное`,source:`https://metallik.ru/articles/sbornoe/`}],articles:[{id:`raschet-listov-profnastila-na-zabor`,title:`Расчет листов профнастила на забор`,description:`Есть два варианта расчета количества профлиста на забор — ручной и автоматический.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/raschet-listov-profnastila-na-zabor/`,sourceDate:`2025-10-01`,sourceDateLabel:`01.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/raschet-listov-profnastila-na-zabor.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/ef838c10b6202116.webp`,width:1280,height:854,alt:`Расчет листов профнастила на забор`}},{id:`elementy-vodostochnoy-sistemy-ustroystvo-vybor-i-raschet`,title:`Элементы водосточной системы – устройство, выбор и расчет`,description:`Надежная водосточная система – это защита фундамента и стен дома от разрушений, вызванных дождевой и талой водой.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/elementy-vodostochnoy-sistemy-ustroystvo-vybor-i-raschet/`,sourceDate:`2025-08-26`,sourceDateLabel:`26.08.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/elementy-vodostochnoy-sistemy-ustroystvo-vybor-i-raschet.json`},{id:`chto-luchshe-dlya-dymokhoda-bazaltovaya-ili-kaolinovaya-vata`,title:`Что лучше для дымохода – базальтовая или каолиновая вата`,description:`Безопасность работы печи, котла или камина напрямую зависит от правильного выбора дымоходной системы.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/chto-luchshe-dlya-dymokhoda-bazaltovaya-ili-kaolinovaya-vata/`,sourceDate:`2025-08-26`,sourceDateLabel:`26.08.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/chto-luchshe-dlya-dymokhoda-bazaltovaya-ili-kaolinovaya-vata.json`},{id:`kriterii-podbora-krovelnogo-materiala`,title:`Критерии подбора кровельного материала`,description:`Полное руководство по выбору кровельных материалов: металлочерепица, профнастил, гибкая черепица, шифер, мембраны, черепица. Сравнение, советы, факты`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/kriterii-podbora-krovelnogo-materiala/`,sourceDate:`2025-08-05`,sourceDateLabel:`05.08.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kriterii-podbora-krovelnogo-materiala.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/cedc17d17c2f9e68.webp`,width:1536,height:1024,alt:`Критерии подбора кровельного материала`}},{id:`vysota-dymokhoda-iz-nerzhaveyushchey-stali`,title:`Высота дымохода из нержавеющей стали: как правильно определить оптимальное положение относительно конька крыши`,description:`В этой статье подробно разберём, как определить правильную высоту дымохода из нержавеющей стали, почему это так важно и какие факторы влияют на выбор высоты.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/vysota-dymokhoda-iz-nerzhaveyushchey-stali/`,sourceDate:`2025-06-04`,sourceDateLabel:`04.06.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vysota-dymokhoda-iz-nerzhaveyushchey-stali.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/d4a2236ca3643c2d.webp`,width:557,height:350,alt:`Высота дымохода из нержавеющей стали: как правильно определить оптимальное положение относительно конька крыши`}},{id:`pochemu-vodostochnaya-sistema-obyazatelnyy-element-kazhdogo-doma`,title:`Почему водосточная система — обязательный элемент каждого дома`,description:`При строительстве дома основное внимание обычно уделяется фундаменту, стенам и кровле. Однако многие забывают о важности водосточной системы, хотя именно она играет ключевую роль в защите здания от разрушительного воздействия влаги. Отсутствие правильно смонтированного водостока может обернуться дорогостоящими ремонтами уже через несколько лет эксплуатации.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/pochemu-vodostochnaya-sistema-obyazatelnyy-element-kazhdogo-doma/`,sourceDate:`2025-05-12`,sourceDateLabel:`12.05.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/pochemu-vodostochnaya-sistema-obyazatelnyy-element-kazhdogo-doma.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/424f564fad586ea6.webp`,width:1280,height:853,alt:`Почему водосточная система — обязательный элемент каждого дома`}},{id:`kak-pravilno-prikrepit-metallicheskiy-shtaketnik-k-zaboru`,title:`Как правильно прикрепить металлический штакетник к забору`,description:`Заборы из металлоштакетника – популярное решение для ограждения территорий, сочетающее в себе долговечность и привлекательный внешний вид. Чтобы такое ограждение прослужило долго, необходимо не только подобрать качественные материалы, но и правильно выполнить монтаж, уделив особое внимание выбору и установке крепежа. В этой статье мы подробно рассмотрим, как правильно зафиксировать элементы ограждения на заборе, какой крепеж лучше всего использовать и какие нюансы следует учитывать для достижения надежного и долговечного результата.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kak-pravilno-prikrepit-metallicheskiy-shtaketnik-k-zaboru/`,sourceDate:`2025-03-26`,sourceDateLabel:`26.03.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-pravilno-prikrepit-metallicheskiy-shtaketnik-k-zaboru.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/b01a52eef7834b8e.webp`,width:1280,height:853,alt:`Как правильно прикрепить металлический штакетник к забору`}},{id:`kakoy-vysoty-mozhno-delat-zabor-iz-profnastila`,title:`Какой высоты можно делать забор из профнастила`,description:`При строительстве ограждения из профнастила важно учитывать не только характеристики самого материала, но и предполагаемую высоту конструкции. Этот параметр напрямую влияет на эффективность выполнения забора своих функций.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/kakoy-vysoty-mozhno-delat-zabor-iz-profnastila/`,sourceDate:`2025-03-25`,sourceDateLabel:`25.03.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kakoy-vysoty-mozhno-delat-zabor-iz-profnastila.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/98c2a557761a6e83.webp`,width:1280,height:853,alt:`Какой высоты можно делать забор из профнастила`}},{id:`kak-pravilno-smontirovat-konek-dlya-krovli-iz-profnastila`,title:`Как правильно смонтировать конек для кровли из профнастила`,description:`Расскажем как рассчитать длину коньковой планки, как подобрать крепеж, а также как надежно закрепить конек на крыше из профнастила.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/kak-pravilno-smontirovat-konek-dlya-krovli-iz-profnastila/`,sourceDate:`2024-12-09`,sourceDateLabel:`09.12.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-pravilno-smontirovat-konek-dlya-krovli-iz-profnastila.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/a67ae0f7aec50ad4.webp`,width:1600,height:533,alt:`Как правильно смонтировать конек для кровли из профнастила`}},{id:`kakoy-dymokhod-luchshe-vybrat-dlya-bani`,title:`Какой дымоход лучше для бани – из нержавейки, керамики или кирпича`,description:`Расскажем какие дымоходы бывают, как правильно выбрать материал для дымохода и какие из них подходят для дровяной печи.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kakoy-dymokhod-luchshe-vybrat-dlya-bani/`,sourceDate:`2024-11-13`,sourceDateLabel:`13.11.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kakoy-dymokhod-luchshe-vybrat-dlya-bani.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/2067452a8b2e98fc.webp`,width:1600,height:896,alt:`Какой дымоход лучше для бани – из нержавейки, керамики или кирпича`}},{id:`zonirovanie-dachnogo-uchastka`,title:`Зонирование дачного участка`,description:`Правильно спланированное зонирование позволяет создать уютные и функциональные зоны, сделать участок более эргономичным и удобным для проведения времени на природе.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/zonirovanie-dachnogo-uchastka/`,sourceDate:`2024-04-03`,sourceDateLabel:`03.04.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/zonirovanie-dachnogo-uchastka.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/154acbdb9b0b10a7.webp`,width:624,height:354,alt:`Зонирование дачного участка`}},{id:`snegozaderzhatel-ploskoovalnyy`,title:`Снегозадержатель плоскоовальный`,description:`Снегозадержатель плоскоовальный эффективно справляется с удержанием снеговых масс, выдерживает повышенные нагрузки, значительно выше нормативных.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/snegozaderzhatel-ploskoovalnyy/`,sourceDate:`2023-10-25`,sourceDateLabel:`25.10.2023`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/snegozaderzhatel-ploskoovalnyy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/1d897b73d54ff9e5.webp`,width:500,height:397,alt:`Снегозадержатель плоскоовальный`}},{id:`ograzhdeniya-zhalyuzi`,title:`Ограждения жалюзи`,description:`Современное и стильное решение, сочетающее в себе функциональность и эстетику`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/ograzhdeniya-zhalyuzi/`,sourceDate:`2023-09-11`,sourceDateLabel:`11.09.2023`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/ograzhdeniya-zhalyuzi.json`},{id:`list-fasadnyy`,title:`Лист фасадный`,description:`Универсальный доступный материал, который используется в качестве облицовки фасадов или в виде забора на любые виды столбов.`,categoryId:`list-fasadnyy`,source:`https://metallik.ru/articles/list-fasadnyy/list-fasadnyy/`,sourceDate:`2023-09-05`,sourceDateLabel:`05.09.2023`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/list-fasadnyy.json`},{id:`sayding`,title:`Сайдинг`,description:`Металлический сайдинг - панели, используемые для облицовки фасадов зданий. Применяются для придания зданию индивидуальности, защиты фасада от погодных воздействий, скрытия внешних коммуникаций.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/sayding/`,sourceDate:`2019-06-05`,sourceDateLabel:`05.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/sayding.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/6c5e5644f363fd9b.webp`,width:1024,height:718,alt:`Сайдинг`}},{id:`dymokhody-metallik_ko`,title:`Дымоходы МЕТАЛЛИК и КО`,description:`Качественный дымоход обеспечивает идеальную тягу, эффективное сжигание топлива, быстрый прогрев стенок топки. Дымоходы МЕТАЛЛИК и КО отличаются прочностью и долговечностью.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/dymokhody-metallik_ko/`,sourceDate:`2019-06-05`,sourceDateLabel:`05.06.2019`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dymokhody-metallik_ko.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/14be29bdd74a4e0a.webp`,width:437,height:311,alt:`Дымоходы МЕТАЛЛИК и КО`}},{id:`shtaketnik-metallicheskiy`,title:`Виды металлического штакетника для забора`,description:`Форма металлического штакетника влияет не только на внешний вид забора, но и на его прочность, а также безопасность эксплуатации. Различают варианты по форме верхней части и по профилю планки.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/shtaketnik-metallicheskiy/`,sourceDate:`2026-03-24`,sourceDateLabel:`24.03.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/shtaketnik-metallicheskiy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/6f91d1cd88483be9.webp`,width:1344,height:683,alt:`Виды металлического штакетника для забора`}},{id:`vodostoki-metallik-i-ko`,title:`Водостоки МЕТАЛЛИК и КО`,description:`Водосточные системы необходимы для сбора и отвода воды с крыш, а также для уменьшения влажности фундаментов и защиты фасадов и цоколя зданий от влаги. Какие особенности водосточных систем МЕТАЛЛИК и КО?`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/vodostoki-metallik-i-ko/`,sourceDate:`2018-09-24`,sourceDateLabel:`24.09.2018`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vodostoki-metallik-i-ko.json`},{id:`metallicheskaya-krovlya`,title:`Металлическая кровля`,description:`Металлическая кровля является универсальным кровельным материалом и монтируется на всех типах поверхностей и конструкций зданий.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/metallicheskaya-krovlya/`,sourceDate:`2018-09-24`,sourceDateLabel:`24.09.2018`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/metallicheskaya-krovlya.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/f6828608e57cecb8.webp`,width:1280,height:958,alt:`Металлическая кровля`}},{id:`profnastil`,title:`Профнастил`,description:`Профнастил относится к современным решениям при возведении перекрытий и ограждений, в качестве кровли и заборов, внешней отделки всевозможных зданий и сооружений.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/profnastil/`,sourceDate:`2018-09-24`,sourceDateLabel:`24.09.2018`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/profnastil.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/6b31bc2b6455c040.webp`,width:1361,height:849,alt:`Профнастил`}},{id:`vorota-zhalyuzi`,title:`Ворота жалюзи`,description:`Комплект жалюзи для ворот представляет собой две одинаковые сборные конструкции, предназначенные для установки в замкнутые проемы рамы откатных ворот.`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/vorota-zhalyuzi/`,sourceDate:`2024-03-12`,sourceDateLabel:`12.03.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vorota-zhalyuzi.json`},{id:`snegozaderzhatel-trubchatyy`,title:`Снегозадержатель трубчатый`,description:`Снегозадержатель эффективно справляется с удержанием снеговых масс, выдерживает повышенные нагрузки, значительно выше нормативных.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/snegozaderzhatel-trubchatyy/`,sourceDate:`2023-10-25`,sourceDateLabel:`25.10.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/snegozaderzhatel-trubchatyy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/1944e44b1e942650.webp`,width:500,height:397,alt:`Снегозадержатель трубчатый`}},{id:`primenenie-lista-fasadnogo`,title:`Применение листа фасадного`,description:`Представляет собой лист металла, покрытый полимерным слоем, обеспечивающим защиту от коррозии и ультрафиолетовых лучей.`,categoryId:`list-fasadnyy`,source:`https://metallik.ru/articles/list-fasadnyy/primenenie-lista-fasadnogo/`,sourceDate:`2023-09-11`,sourceDateLabel:`11.09.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/primenenie-lista-fasadnogo.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/4fbb9ab6529fe951.webp`,width:800,height:450,alt:`Применение листа фасадного`}},{id:`vidy-profnastila11`,title:`Виды профнастила`,description:`Листы профнастила маркируют буквенно - цифровым значением, в котором буква означает назначение профнастила, а цифра - высоту волны профиля. Показатели высоты будут в диапазоне от 6 до 114 мм.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/vidy-profnastila11/`,sourceDate:`2023-02-08`,sourceDateLabel:`08.02.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vidy-profnastila11.json`},{id:`montazh-shtaketnika`,title:`Установка металлического штакетника своими руками`,description:`Металлический штакетник — это практичное и долговечное решение для ограждения участка. Такой забор сочетает в себе прочность, эстетичный внешний вид и простоту установки. При этом монтаж штакетника можно выполнить самостоятельно, без привлечения специалистов`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/montazh-shtaketnika/`,sourceDate:`2026-04-02`,sourceDateLabel:`02.04.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-shtaketnika.json`},{id:`nerzhaveyushchaya-i-otsinkovannaya-stali`,title:`Нержавеющая и оцинкованная стали`,description:`Выбор материалов - ответственный и сложный этап строительства дома. При всем многообразии существующих материалов металл является одним из самых востребованных.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/nerzhaveyushchaya-i-otsinkovannaya-stali/`,sourceDate:`2022-09-15`,sourceDateLabel:`15.09.2022`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/nerzhaveyushchaya-i-otsinkovannaya-stali.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/de78f77f55de5ada.webp`,width:1461,height:911,alt:`Нержавеющая и оцинкованная стали`}},{id:`elementy-bezopasnosti-krovli1`,title:`Что такое элементы безопасности кровли`,description:`Элементы безопасности кровли защищают кровлю от схода снега и льда, а также используются для обеспечения дополнительной защитной функции при монтаже/ремонте кровли`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/elementy-bezopasnosti-krovli1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/elementy-bezopasnosti-krovli1.json`},{id:`kalkulyator-dymokhodov`,title:`Калькулятор дымоходов`,description:`Используя калькулятор для расчета дымохода, вы сможете быстро и легко подобрать необходимые элементы дымохода, а также получить примерное представление о стоимости системы дымоотведения.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kalkulyator-dymokhodov/`,sourceDate:`2021-12-01`,sourceDateLabel:`01.12.2021`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kalkulyator-dymokhodov.json`},{id:`kak-rasschitat-vodostok`,title:`Как рассчитать водосток?`,description:`Рассказываем как рассчитать необходимые элементы водосточной системы и что необходимо учесть при расчетах.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/kak-rasschitat-vodostok/`,sourceDate:`2020-02-13`,sourceDateLabel:`13.02.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-rasschitat-vodostok.json`},{id:`montazh-saydingovykh-paneley`,title:`Монтаж сайдинговых панелей`,description:`Рассказываем как подготовить панели к монтажу, как правильно смонтировать сайдинг и как решить задачи, с которыми вы можете столкнуться во время монтажа.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/montazh-saydingovykh-paneley/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-saydingovykh-paneley.json`},{id:`montazh-metallicheskoy-krovli`,title:`Монтаж металлической кровли`,description:`Монтаж металлической кровли является одним из важнейших этапов в использовании кровли. Рассказываем о нюансах монтажа.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/montazh-metallicheskoy-krovli/`,sourceDate:`2019-06-14`,sourceDateLabel:`14.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-metallicheskoy-krovli.json`},{id:`kalitki-zhalyuzi`,title:`Калитки жалюзи`,description:`Представляет собой сборную конструкцию, предназначенную для установки в замкнутые проемы рамы калитки.`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/kalitki-zhalyuzi/`,sourceDate:`2024-03-12`,sourceDateLabel:`12.03.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kalitki-zhalyuzi.json`},{id:`luchshaya-krovlya-dlya-dachi`,title:`Лучшая кровля для дачи`,description:`При выборе кровли для дачи существует несколько важных аспектов, которые следует учитывать. Тип кровли должен быть подходящим как по функциональности, так и по эстетическим параметрам.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/luchshaya-krovlya-dlya-dachi/`,sourceDate:`2024-01-25`,sourceDateLabel:`25.01.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/luchshaya-krovlya-dlya-dachi.json`},{id:`montazh-snegozaderzhatelya-ploskoovalnogo`,title:`Монтаж снегозадержателя плоскоовального`,description:`Порядок монтажа снегозадержателя плоскоовального, нюансы и особенности.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/montazh-snegozaderzhatelya-ploskoovalnogo/`,sourceDate:`2023-10-25`,sourceDateLabel:`25.10.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-snegozaderzhatelya-ploskoovalnogo.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/061abbb28ca50d6a.webp`,width:1368,height:896,alt:`Монтаж снегозадержателя плоскоовального`}},{id:`komfortnaya-udalenka-na-dache`,title:`Комфортная "удаленка" на даче`,description:`Пандемия заметно повлияла на образ нашей жизни. Во время карантина многие перешли на удаленный формат работы, ведь один из главных плюсов "удалёнки" - возможность трудиться из любого места.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/komfortnaya-udalenka-na-dache/`,sourceDate:`2022-09-16`,sourceDateLabel:`16.09.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/komfortnaya-udalenka-na-dache.json`},{id:`dostoinstva-metallicheskoy-krovli`,title:`Достоинства металлической кровли`,description:`Металлическая кровля является безусловным фаворитом, ей отдают предпочтение 65% россиян, и не зря: металлочерепица долговечна, стоит относительно недорого и достойно выглядит.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/dostoinstva-metallicheskoy-krovli/`,sourceDate:`2022-09-15`,sourceDateLabel:`15.09.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dostoinstva-metallicheskoy-krovli.json`},{id:`smezhnyy-zabor-mezhdu-sosedyami`,title:`Смежный забор между соседями`,description:`Быть в ладах с соседями по даче всегда приятно и полезно: можно устраивать совместные посиделки у костра, турниры по волейболу, помогать друг другу со строительством и ремонтом.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/smezhnyy-zabor-mezhdu-sosedyami/`,sourceDate:`2022-08-17`,sourceDateLabel:`17.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/smezhnyy-zabor-mezhdu-sosedyami.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/f810dd06fc2a3dfa.webp`,width:1141,height:808,alt:`Смежный забор между соседями`}},{id:`strana-glukhikh-zaborov1`,title:`Страна глухих заборов`,description:`Забор - неотъемлемая часть любого загородного участка. Живые изгороди, низенькие деревянные перегородки, высокие бетонные стены и металлические листы – все это варианты того, как люди огораживают свою частную жизнь.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/strana-glukhikh-zaborov1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/strana-glukhikh-zaborov1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/4232ec8c40105885.webp`,width:450,height:419,alt:`Страна глухих заборов`}},{id:`dobornye-elementy-saydinga`,title:`Доборные элементы сайдинга`,description:`Доборные элементы - это декоративные элементы, применяемые для облицовки стен сайдингом, на стыках, углах, откосах. Доборные элементы подразделяются на сложные, простые и сборные.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/dobornye-elementy-saydinga/`,sourceDate:`2020-09-30`,sourceDateLabel:`30.09.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dobornye-elementy-saydinga.json`},{id:`montazh-dobornykh-elementov`,title:`Монтаж доборных элементов`,description:`Доборные элементы необходимы для защиты стыков кровли и стен от попадания влаги, мусора, ветра в подкровельное пространство.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/montazh-dobornykh-elementov/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-dobornykh-elementov.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/904d98e091ee00bd.webp`,width:1368,height:896,alt:`Монтаж доборных элементов`}},{id:`krovelnyy-pirog`,title:`Кровельный пирог`,description:`Что такое кровельный пирог: устройство и особенности утепления крыши В этой статье расскажем про кровельный пирог: что это такое, какие элементы обязательны в крыше, а также дадим рекомендации по укладке кровельного пирога.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/krovelnyy-pirog/`,sourceDate:`2019-06-14`,sourceDateLabel:`14.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/krovelnyy-pirog.json`},{id:`montazh-vodostochnoy-sistemy`,title:`Монтаж водосточной системы: пошаговая инструкция`,description:`Правильный монтаж водосточной системы обеспечивает ее эффективную работу, а также повышает срок службы водостока. Рассказываем нюансы монтажа.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/montazh-vodostochnoy-sistemy/`,sourceDate:`2019-06-14`,sourceDateLabel:`14.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-vodostochnoy-sistemy.json`},{id:`montazh-dymokhodov`,title:`Монтаж дымохода: правила установки, сборка и крепление трубы`,description:`Какое бы топливо мы не использовали, образуются продукты сгорания. Ошибки при монтаже отопительной системы могут стать причиной пожара или образования смертельно опасного угарного газа.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/montazh-dymokhodov/`,sourceDate:`2019-06-04`,sourceDateLabel:`04.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-dymokhodov.json`},{id:`v-kakom-stile-obustroit-zagorodnyy-dom`,title:`В каком стиле обустроить загородный дом`,description:`Стили дизайна загородного дома - это ключевой элемент создания уютной и стильной обстановки.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/v-kakom-stile-obustroit-zagorodnyy-dom/`,sourceDate:`2024-04-11`,sourceDateLabel:`11.04.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/v-kakom-stile-obustroit-zagorodnyy-dom.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/32cea44118cc7d68.webp`,width:504,height:336,alt:`В каком стиле обустроить загородный дом`}},{id:`sektsii-zhalyuzi`,title:`Секции жалюзи`,description:`Готовые секции в качестве ограждений под любую задачу.`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/sektsii-zhalyuzi/`,sourceDate:`2023-07-12`,sourceDateLabel:`12.07.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/sektsii-zhalyuzi.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/35d3016de6c33ee0.webp`,width:1214,height:821,alt:`Секции жалюзи`}},{id:`vygodnaya-sdelka-kogda-luchshe-pokupat-dachu-`,title:`Выгодная сделка: когда лучше покупать дачу?`,description:`Обычно Металич дает ответы на дачные вопросы для тех, у кого уже есть свой дом и участок, но в этот раз хочет помочь тем, кто отчаянно хочет обзавестись дачей, но пока этого не сделал.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/vygodnaya-sdelka-kogda-luchshe-pokupat-dachu-/`,sourceDate:`2023-01-25`,sourceDateLabel:`25.01.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vygodnaya-sdelka-kogda-luchshe-pokupat-dachu-.json`},{id:`chem-zanyatsya-na-dache-v-dozhd`,title:`Чем заняться на даче в дождливые дни`,description:`Лето, солнце, тёплый ветер - идеальные партнеры дачного отдыха. Миллион планов сразу выстраивается в голове: постричь газон, установить дымоход в новенькой бане и обязательно дойти до речки.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/chem-zanyatsya-na-dache-v-dozhd/`,sourceDate:`2022-08-05`,sourceDateLabel:`05.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/chem-zanyatsya-na-dache-v-dozhd.json`},{id:`vodostochnaya-sistema-bolshogo-diametra`,title:`Водосточная система большого диаметра`,description:`Водостоки большого диаметра рекомендованы для кровель с увеличенной площадью многоэтажных жилых домов, муниципальных зданий, промышленного и гражданского строительства.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/vodostochnaya-sistema-bolshogo-diametra/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vodostochnaya-sistema-bolshogo-diametra.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/770d638f2408364b.webp`,width:242,height:134,alt:`Водосточная система большого диаметра`}},{id:`odnokonturnye-i-dvukhkonturnye-dymokhody`,title:`Одноконтурные и двухконтурные дымоходы`,description:`В чем различие одноконтурного и двухконтурного дымоходов? Рассказываем что и в каких случаях правильнее выбрать.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/odnokonturnye-i-dvukhkonturnye-dymokhody/`,sourceDate:`2019-06-08`,sourceDateLabel:`08.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/odnokonturnye-i-dvukhkonturnye-dymokhody.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/ce3b366ed6331b33.webp`,width:1214,height:821,alt:`Одноконтурные и двухконтурные дымоходы`}},{id:`sofity`,title:`Софиты`,description:`Металлические софиты применяются для обшивки фронтонных и карнизных свесов крыши. Придают завершенный вид дому, обеспечения вентиляции подкровельного пространства.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/sofity/`,sourceDate:`2019-06-05`,sourceDateLabel:`05.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/sofity.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/fe9d9b32796f862b.webp`,width:260,height:223,alt:`Софиты`}},{id:`na-trope-druzhby-s-sosedyami`,title:`На тропе дружбы с соседями`,description:`Культура близкого общения с соседями уходит в прошлое. Большинство городских жителей уже давно не ходят к соседям «за солью», а зачастую даже не знают их имен.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/na-trope-druzhby-s-sosedyami/`,sourceDate:`2022-08-17`,sourceDateLabel:`17.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/na-trope-druzhby-s-sosedyami.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/a3a374d09152e98c.webp`,width:417,height:277,alt:`На тропе дружбы с соседями`}},{id:`preimushchestva-metallicheskogo-saydinga`,title:`Преимущества металлического сайдинга`,description:`Мы уделяем большое внимание качеству нашей продукции, ее долговечности и внешнему виду, поэтому наш сайдинг имеет ряд преимуществ.Рассказываем о них подробно.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/preimushchestva-metallicheskogo-saydinga/`,sourceDate:`2020-07-03`,sourceDateLabel:`03.07.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/preimushchestva-metallicheskogo-saydinga.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/96801a3be6a27ad5.webp`,width:510,height:542,alt:`Преимущества металлического сайдинга`}},{id:`dymokhody-premium1`,title:`Дымоходы Premium`,description:`Дымоходы Премиум - это серия дымоходов из аустенитных марок стали толщиной 0,5 - 1 мм. Элементы этой серии изготавливаются с применением лазерной сварки и раструбной системы соединений.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/dymokhody-premium1/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dymokhody-premium1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/e692a134385479fb.webp`,width:895,height:501,alt:`Дымоходы Premium`}},{id:`montazh-vodostochnoy-sistemy-bolshogo-diametra`,title:`Монтаж водосточной системы большого диаметра`,description:`Правильный монтаж водосточной системы больного диаметра обеспечивает ее эффективную работу, а также повышает срок службы водостока. Рассказываем нюансы монтажа.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/montazh-vodostochnoy-sistemy-bolshogo-diametra/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-vodostochnoy-sistemy-bolshogo-diametra.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/06fd03adf9c70dd7.webp`,width:913,height:913,alt:`Монтаж водосточной системы большого диаметра`}},{id:`kak-vybrat-dymokhod`,title:`Как выбрать дымоход правильной конструкции для различных отопительных приборов`,description:`От правильного выбора дымохода зависит его эффективность, а также безопасность дымоходной системы. Рассмотрим основные критерии, по которым выбирается дымоход.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kak-vybrat-dymokhod/`,sourceDate:`2019-06-04`,sourceDateLabel:`04.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-vybrat-dymokhod.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/03573175b5d4ac4a.webp`,width:449,height:479,alt:`Как выбрать дымоход правильной конструкции для различных отопительных приборов`}},{id:`chem-polezna-banya`,title:`В чем польза бани?`,description:`Расскажем какие дымоходы бывают, как правильно выбрать материал для дымохода и какие из них подходят для дровяной печи.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/chem-polezna-banya/`,sourceDate:`2022-08-23`,sourceDateLabel:`23.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/chem-polezna-banya.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/2cb50b8d122f3626.webp`,width:1024,height:771,alt:`В чем польза бани?`}},{id:`tsvetovye-resheniya`,title:`Цветовые решения`,description:`Рассказываем о видах цветных покрытий, которые используются в производстве продукции МЕТАЛЛИК и КО.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/tsvetovye-resheniya/`,sourceDate:`2021-06-10`,sourceDateLabel:`10.06.2021`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/tsvetovye-resheniya.json`},{id:`montazh-snegozaderzhatelya`,title:`Инструкция по установке трубчатого снегозадержателя (3 метра)`,description:`Установка снегозадержателей необходима для предотвращения внезапного схода масс снега с крыши в зимнее и весеннее время.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/montazh-snegozaderzhatelya/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-snegozaderzhatelya.json`},{id:`komplekt-dymokhoda`,title:`Комплект дымохода`,description:`Для удобства клиентов мы разработали универсальное решение - готовые комплекты дымоходов. Комплект содержит все необходимые конструкционные элементы и легко помещается в автомобиль.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/komplekt-dymokhoda/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/komplekt-dymokhoda.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/a45f89d72607da8d.webp`,width:685,height:581,alt:`Комплект дымохода`}},{id:`komplektuyushchie-i-dobornye-elementy`,title:`Как выбрать комплектующие и доборные элементы для кровли`,description:`Доборные элементы кровли - это различные по конфигурации планки, без которых невозможно обойтись в кровле, фасадах зданий.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/komplektuyushchie-i-dobornye-elementy/`,sourceDate:`2018-09-24`,sourceDateLabel:`24.09.2018`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/komplektuyushchie-i-dobornye-elementy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/88d3bf943b0dcd89.webp`,width:260,height:223,alt:`Как выбрать комплектующие и доборные элементы для кровли`}},{id:`vodostok-metall-ili-plastik`,title:`Водосток: металл или пластик?`,description:`Принципиальным параметром выбора водостока является материал, из которого он изготовлен. Итак, какой водосток: металлический или пластиковый?.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/vodostok-metall-ili-plastik/`,sourceDate:`2023-11-02`,sourceDateLabel:`02.11.2023`,editorChoice:!0,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/vodostok-metall-ili-plastik.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/eec0b1c16cc17432.webp`,width:1368,height:896,alt:`Водосток: металл или пластик?`}},{id:`postroit-dom-svoimi-rukami`,title:`Построить дом своими руками`,description:`Жизнь за городом привлекает людей по многим причинам: близость к природе, экология, свой сад, ощущение большей свободы - все эти преимущества не оставляют равнодушными даже заядлых любителей городской жизни.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/postroit-dom-svoimi-rukami/`,sourceDate:`2022-08-23`,sourceDateLabel:`23.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/postroit-dom-svoimi-rukami.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/fdeb0a74a3496fd4.webp`,width:450,height:323,alt:`Построить дом своими руками`}},{id:`montazh-krovelnogo-ograzhdeniya`,title:`Монтаж кровельного ограждения`,description:`Кровельное ограждение предназначено для обеспечения безопасности людей при передвижении по кровле и предотвращения их падения при эксплуатации, ремонте и обслуживании кровли.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/montazh-krovelnogo-ograzhdeniya/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/montazh-krovelnogo-ograzhdeniya.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/1df2cb8c3ccfeb5e.webp`,width:448,height:438,alt:`Монтаж кровельного ограждения`}},{id:`tsvetnye-dymokhody`,title:`Цветные дымоходы`,description:`При проходе дымохода через улицу по фасаду здания стоит учитывать единую дизайнерскую концепцию строения. Подходящим вариантом будет применение дымохода в цвет фасада здания или в цвет кровли.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/tsvetnye-dymokhody/`,sourceDate:`2019-06-08`,sourceDateLabel:`08.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/tsvetnye-dymokhody.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/1eaaa4168ee492f9.webp`,width:450,height:441,alt:`Цветные дымоходы`}},{id:`dom-v-lyubimykh-tsvetakh-standarta-ral`,title:`Дом в любимых цветах. Стандарт RAL`,description:`Думая о том, какими мы хотим видеть наш загородный дом и участок, мы сталкиваемся с проблемой выбора цветов материалов. О том, как выбрать цвета, которые не будут надоедать, - в этой статье.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/dom-v-lyubimykh-tsvetakh-standarta-ral/`,sourceDate:`2022-09-20`,sourceDateLabel:`20.09.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dom-v-lyubimykh-tsvetakh-standarta-ral.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/a0321c3111b9a056.webp`,width:450,height:424,alt:`Дом в любимых цветах. Стандарт RAL`}},{id:`koe-chto-o-vodostoke1`,title:`Кое-что о водостоке`,description:`Дождевая и талая вода со временем разрушает фасад и фундамент дома. Чтобы это предотвратить, важно выбрать надежную водосточную систему. Мы расскажем на что обязательно нужно обратить внимание.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/koe-chto-o-vodostoke1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/koe-chto-o-vodostoke1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/cc5774427867d20e.webp`,width:1024,height:1024,alt:`Кое-что о водостоке`}},{id:`gryadka-sadovaya`,title:`Грядка садовая`,description:`Оцинкованные грядки с полимерным покрытием предназначены для формирования ровных рядов под посадку различных растений на участке, а также для зонирования территории.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/gryadka-sadovaya/`,sourceDate:`2020-09-16`,sourceDateLabel:`16.09.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/gryadka-sadovaya.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/4a8b0bb3305f0c43.webp`,width:500,height:397,alt:`Грядка садовая`}},{id:`promyshlennye-dymokhody`,title:`Промышленные дымоходы`,description:`Промышленный дымоход обеспечивает отвод и удаление продуктов сгорания разных видов топлива (уголь, нефть, газ, биотопливо, твёрдое топливо, сжиженный углеводород) от оборудования малой, средней и большой мощности.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/promyshlennye-dymokhody/`,sourceDate:`2020-01-16`,sourceDateLabel:`16.01.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/promyshlennye-dymokhody.json`},{id:`tsvet-kotoryy-ne-nadoest`,title:`Цвет, который не надоест`,description:`Во время строительства собственного дома приходится продумывать множеств важных моментов. Такая деталь, как цвет фасада или забора, кажется незначительной в сравнении с укладкой фундамента, системой коммуникаций и проектированием крыши.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/tsvet-kotoryy-ne-nadoest/`,sourceDate:`2022-09-05`,sourceDateLabel:`05.09.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/tsvet-kotoryy-ne-nadoest.json`},{id:`teploizolyatsiya-dymokhodov`,title:`Теплоизоляция дымоходов`,description:`Утеплитель защищает металлические трубы дымохода от конденсата и резких перепадов температур. Он продлевает срок службы системы. Без теплоизоляции трубы дымохода со временем начнут разрушаться из-за накопившейся влаги.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/teploizolyatsiya-dymokhodov/`,sourceDate:`2020-08-13`,sourceDateLabel:`13.08.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/teploizolyatsiya-dymokhodov.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/cacfe4ec2fed8abc.webp`,width:1024,height:560,alt:`Теплоизоляция дымоходов`}},{id:`pochemu-dacha-delaet-nas-schastlivee`,title:`Почему дача делает нас счастливее?`,description:`Определенно, счастье для каждого своё, и все же есть вещи, приносящие радость большинству. Что если многие из простых радостей, способных сделать нас счастливыми, сосредоточились в одном любимом месте?`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/pochemu-dacha-delaet-nas-schastlivee/`,sourceDate:`2022-11-15`,sourceDateLabel:`15.11.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/pochemu-dacha-delaet-nas-schastlivee.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/15e6480a66c1f148.webp`,width:1e3,height:700,alt:`Почему дача делает нас счастливее?`}},{id:`marki-stali-dymokhodov`,title:`Марки стали дымоходов`,description:`Оцинкованная сталь - металл, который защищен от коррозии слоем цинка. Оцинковка устойчива к воздействию агрессивных сред, механическим воздействиям, деформации. Может использоваться без дополнительной обработки.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/marki-stali-dymokhodov/`,sourceDate:`2022-01-31`,sourceDateLabel:`31.01.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/marki-stali-dymokhodov.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/b9bf7f937b75962f.webp`,width:1326,height:901,alt:`Марки стали дымоходов`}},{id:`pechi-kaminy-kotly-uzpo`,title:`Печи/камины/котлы УЗПО`,description:`Жарсталь - торговая марка уральского завода печного оборудования. Продукция: банные печи каменки, отопительные котлы и печи.`,categoryId:``,source:`https://metallik.ru/articles/pechi-i-kotly/pechi-kaminy-kotly-uzpo/`,sourceDate:`2021-03-24`,sourceDateLabel:`24.03.2021`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/pechi-kaminy-kotly-uzpo.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/6cd2d3bd27ec0efe.webp`,width:1213,height:911,alt:`Печи/камины/котлы УЗПО`}},{id:`zonirovanie-prostranstva-v-dome`,title:`Зонирование пространства в доме`,description:`Думая о загородном доме мечты, как правило, все представляют жилище с множеством различных комнат: вот просторная кухня, светлая детская, комната для отдыха, а вот место для посиделок с гостями.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/zonirovanie-prostranstva-v-dome/`,sourceDate:`2023-01-25`,sourceDateLabel:`25.01.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/zonirovanie-prostranstva-v-dome.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/801903881cf97177.webp`,width:504,height:336,alt:`Зонирование пространства в доме`}},{id:`kak-ne-zamerznut-na-dache-zimoy`,title:`Как не замерзнуть на даче зимой`,description:`О посещении дачи в зимнее время года лучше думать заранее. Если вы хотите ездить в свой загородный домик зимой на регулярной основе, то об этом стоит позаботиться уже летом.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/kak-ne-zamerznut-na-dache-zimoy/`,sourceDate:`2022-11-29`,sourceDateLabel:`29.11.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-ne-zamerznut-na-dache-zimoy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/9e03214be0ee403b.webp`,width:567,height:485,alt:`Как не замерзнуть на даче зимой`}},{id:`zabluzhdeniya-o-teploizolyatsii1`,title:`Теплоизоляция - то, в чем вы сомневались`,description:`Если вы планируете установить новый дымоход, обязательно подумайте о теплоизоляции. Это то, от чего зависит ваша безопасность и исправность всей отопительной системы. Поможем разобраться в главных заблуждениях.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/zabluzhdeniya-o-teploizolyatsii1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/zabluzhdeniya-o-teploizolyatsii1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/7a4a50a7bf78a4cb.webp`,width:714,height:475,alt:`Теплоизоляция - то, в чем вы сомневались`}},{id:`gotovim-dachu-k-zime`,title:`Как подготовить дачу к зиме`,description:`Дачный сезон подходит к концу, дети возвращаются в школу, а мы морально готовимся к наступлению осени и зимы. Но что еще требует подготовки к холодам, так это загородные дома и участки.`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/gotovim-dachu-k-zime/`,sourceDate:`2022-08-31`,sourceDateLabel:`31.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/gotovim-dachu-k-zime.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/b04efb185463cf9e.webp`,width:500,height:390,alt:`Как подготовить дачу к зиме`}},{id:`dymokhody-prosluzhashchie-20-let1`,title:`Дымоходы, которые прослужат более 20 лет`,description:`Дымоходная система любого дома должна быть безопасной. Но не все дымоходы отвечают этому требованию. Часто в трубах скапливается сажа и другие продукты горения, появляется риск задымления или даже пожара.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/dymokhody-prosluzhashchie-20-let1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dymokhody-prosluzhashchie-20-let1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/7629d43bcb281cb5.webp`,width:1272,height:906,alt:`Дымоходы, которые прослужат более 20 лет`}},{id:`kak-vybrat-krovelnyy-material-dlya-dachi`,title:`Как выбрать кровельный материал для дачи`,description:`Рассказываем основные шаги, чтобы не промахнуться при выборе кровли.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/kak-vybrat-krovelnyy-material-dlya-dachi/`,sourceDate:`2024-01-25`,sourceDateLabel:`25.01.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-vybrat-krovelnyy-material-dlya-dachi.json`},{id:`kupit-i-ne-pozhalet1`,title:`Купить и не пожалеть`,description:`Капитальный ремонт дома или дачи - это всегда стресс и большие денежные траты. Как выбрать качественный водосток, дымоход, кровлю и при этом сэкономить семейный бюджет?`,categoryId:`sbornoe`,source:`https://metallik.ru/articles/sbornoe/kupit-i-ne-pozhalet1/`,sourceDate:`2022-08-03`,sourceDateLabel:`03.08.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kupit-i-ne-pozhalet1.json`},{id:`uplotnitel-master-flesh`,title:`Уплотнитель «Мастер Флеш»`,description:`«Мастер Флеш» - это силиконовый уплотнительный элемент, предназначенный для герметизации различных отверстий в кровле.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/uplotnitel-master-flesh/`,sourceDate:`2019-06-09`,sourceDateLabel:`09.06.2019`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/uplotnitel-master-flesh.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/554bff23b4b4621d.webp`,width:696,height:424,alt:`Уплотнитель «Мастер Флеш»`}},{id:`podkrovelnye-plenki-teraspan`,title:`Подкровельные пленки Тераспан`,description:`Торговая марка ТЕРАСПАН занимает достойное место среди Российских строительных изоляционных материалов. Плёнки отлично зарекомендовали себя среди строителей.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/podkrovelnye-plenki-teraspan/`,sourceDate:`2020-12-03`,sourceDateLabel:`03.12.2020`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/podkrovelnye-plenki-teraspan.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/44dc263dbe98a17b.webp`,width:481,height:423,alt:`Подкровельные пленки Тераспан`}},{id:`kak-udachno-vybrat-postavshchika-dymokhodov-chast-1`,title:`Как выбрать производителя дымоходов, часть 1`,description:`Подробно рассказываем как удачно выбрать производителя дымоходов и остаться довольным продукцией`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kak-udachno-vybrat-postavshchika-dymokhodov-chast-1/`,sourceDate:`2023-10-03`,sourceDateLabel:`03.10.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-udachno-vybrat-postavshchika-dymokhodov-chast-1.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/b9d88aaad22c5b5d.webp`,width:514,height:345,alt:`Как выбрать производителя дымоходов, часть 1`}},{id:`kak-vybrat-proizvoditelya-dymokhodov-chast-2`,title:`Как выбрать производителя дымоходов, часть 2`,description:`Продолжаем рассказ о том, как удачно выбрать производителя дымоходов и остаться довольным продукцией`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kak-vybrat-proizvoditelya-dymokhodov-chast-2/`,sourceDate:`2023-10-03`,sourceDateLabel:`03.10.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-vybrat-proizvoditelya-dymokhodov-chast-2.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/c0649ef645bbe105.webp`,width:514,height:345,alt:`Как выбрать производителя дымоходов, часть 2`}},{id:`diametr-dymokhoda`,title:`Диаметр дымохода: как рассчитать сечение трубы для печи, котла и камина`,description:`Как рассчитать диаметр дымохода: формула по мощности, таблицы для банной печи, буржуйки, котла и камина, нормы для кирпичного канала и частые ошибки.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/diametr-dymokhoda/`,sourceDate:`2026-08-19`,sourceDateLabel:`19.08.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/diametr-dymokhoda.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/42e3698900b1a666.webp`,width:928,height:495,alt:`Диаметр дымохода: как рассчитать сечение трубы для печи, котла и камина`}},{id:`raschet-metallocherepitsy-na-kryshu`,title:`Расчет металлочерепицы на крышу: как посчитать количество листов`,description:`Металлочерепицу считают не по площади крыши, а по полезной ширине листа: соседние листы кладут с нахлестом, поэтому материала всегда уходит больше, чем показывает рулетка. Расчет идет в четыре шага: замерить скаты, посчитать их площадь, подобрать длину листа и разделить ширину ската на полезную ширину 1,1 м с округлением вверх. Ниже – формулы, таблицы нахлестов и полный пример с цифрами`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/raschet-metallocherepitsy-na-kryshu/`,sourceDate:`2026-08-19`,sourceDateLabel:`19.08.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/raschet-metallocherepitsy-na-kryshu.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/3cf349fb3c6c0ebf.webp`,width:1195,height:751,alt:`Расчет металлочерепицы на крышу: как посчитать количество листов`}},{id:`kak-ustanovit-otkatnye-vorota`,title:`Откатные ворота: как установить своими руками и что учесть перед покупкой`,description:``,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kak-ustanovit-otkatnye-vorota/`,sourceDate:`2026-05-20`,sourceDateLabel:`20.05.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-ustanovit-otkatnye-vorota.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/8923b250eb63af85.webp`,width:1004,height:723,alt:`Откатные ворота: как установить своими руками и что учесть перед покупкой`}},{id:`kak-ustanovit-stolby-dlya-zabora`,title:`Как правильно установить столбы для забора: глубина, способы монтажа и установка лаг`,description:``,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kak-ustanovit-stolby-dlya-zabora/`,sourceDate:`2026-05-18`,sourceDateLabel:`18.05.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-ustanovit-stolby-dlya-zabora.json`},{id:`kak-montirovat-zabor-zhalyuzi-kak-ustanovit-i-sobrat`,title:`Как монтировать забор жалюзи: как установить и собрать`,description:`Ограждения-жалюзи – это современное и стильное решение как для частного дома с садовым участком, так и для объектов муниципального и гражданского назначения. Тренд, который становится все более популярным.`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/kak-montirovat-zabor-zhalyuzi-kak-ustanovit-i-sobrat/`,sourceDate:`2026-05-18`,sourceDateLabel:`18.05.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-montirovat-zabor-zhalyuzi-kak-ustanovit-i-sobrat.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/a6757d5350126132.webp`,width:1536,height:1024,alt:`Как монтировать забор жалюзи: как установить и собрать`}},{id:`chto-delat-chtoby-ne-bylo-kondensata-v-dymokhode`,title:`Что делать, чтобы не было конденсата в дымоходе`,description:`Рассказываем о причинах образования конденсата в трубе дымохода и как от него избавиться.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/chto-delat-chtoby-ne-bylo-kondensata-v-dymokhode/`,sourceDate:`2026-03-02`,sourceDateLabel:`02.03.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/chto-delat-chtoby-ne-bylo-kondensata-v-dymokhode.json`},{id:`kak-pochistit-dymokhod-svoimi-rukami`,title:`Как почистить дымоход своими руками`,description:`Рассказываем о способах чистки дымохода своими руками и что делать,чтобы дымоход не забивался`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kak-pochistit-dymokhod-svoimi-rukami/`,sourceDate:`2026-02-26`,sourceDateLabel:`26.02.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-pochistit-dymokhod-svoimi-rukami.json`},{id:`kak-predotvratit-zasory-v-vodostokakh-posle-snegopadov`,title:`Как предотвратить засоры в водостоках после снегопадов`,description:`После зимних снегопадов владельцы частных домов часто сталкиваются с проблемой засоров в водостоках. Когда снег начинает таять, вода должна свободно стекать с крыши, но если водостоки забиты льдом, снегом или листьями, это может привести к затоплению фасада, повреждению кровли и даже фундамента.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/kak-predotvratit-zasory-v-vodostokakh-posle-snegopadov/`,sourceDate:`2026-02-03`,sourceDateLabel:`03.02.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-predotvratit-zasory-v-vodostokakh-posle-snegopadov.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/9b049685a7a98b45.webp`,width:512,height:341,alt:`Как предотвратить засоры в водостоках после снегопадов`}},{id:`kak-vybrat-metallicheskiy-zabor-dlya-uchastka`,title:`Как выбрать металлический забор для вашего участка`,description:`Выбор металлического забора — это важный шаг для каждого владельца загородного участка, который хочет обеспечить безопасность, стиль и долговечность ограждения.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/kak-vybrat-metallicheskiy-zabor-dlya-uchastka/`,sourceDate:`2026-02-03`,sourceDateLabel:`03.02.2026`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-vybrat-metallicheskiy-zabor-dlya-uchastka.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/81828aa49408befe.webp`,width:512,height:293,alt:`Как выбрать металлический забор для вашего участка`}},{id:`podgotovka-metallicheskoy-kryshi-k-zime-7-uzlov-dlya-proverki`,title:`Подготовка металлической кровли к зиме: семь участков, требующих контроля`,description:`Какие узлы металлической крыши нужно проверить перед зимой: карниз, конек, примыкания, снегозадержатели, водосток, крепеж и стыки покрытия. Практические рекомендации эксперта по подготовке кровли к холодному сезону.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/podgotovka-metallicheskoy-kryshi-k-zime-7-uzlov-dlya-proverki/`,sourceDate:`2025-12-11`,sourceDateLabel:`11.12.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/podgotovka-metallicheskoy-kryshi-k-zime-7-uzlov-dlya-proverki.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/66bdb09ffa815019.webp`,width:512,height:293,alt:`Подготовка металлической кровли к зиме: семь участков, требующих контроля`}},{id:`kak-zashchitit-vodostok-ot-skhoda-pervogo-snega-s-metallicheskoy-kryshi`,title:`Надежная зима для дома: как защитить водосток от схода первого снега с металлической крыши`,description:`Пошаговые рекомендации, как защитить водосток от схода первого снега с металлической крыши: выбор снегозадержателей, правильный монтаж водостока, кабельный подогрев и сезонное обслуживание.`,categoryId:`vodostochnaya-sistema`,source:`https://metallik.ru/articles/vodostochnaya-sistema/kak-zashchitit-vodostok-ot-skhoda-pervogo-snega-s-metallicheskoy-kryshi/`,sourceDate:`2025-12-11`,sourceDateLabel:`11.12.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-zashchitit-vodostok-ot-skhoda-pervogo-snega-s-metallicheskoy-kryshi.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/e3ab946f7a090b37.webp`,width:316,height:316,alt:`Надежная зима для дома: как защитить водосток от схода первого снега с металлической крыши`}},{id:`snegozaderzhateli-dlya-uzhe-smontirovannoy-kryshi`,title:`Снегозадержатели для уже смонтированной крыши: что выбрать, если о них не подумали заранее`,description:`Как правило, дооснастить кровлю снегозадержателями в большинстве случаев реально, но важно не просто «прикрутить что-то по карнизу», а подобрать решение, согласованное с типом покрытия, геометрией скатов и снеговой нагрузкой в регионе.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/snegozaderzhateli-dlya-uzhe-smontirovannoy-kryshi/`,sourceDate:`2025-12-09`,sourceDateLabel:`09.12.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/snegozaderzhateli-dlya-uzhe-smontirovannoy-kryshi.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/260e112ead791154.webp`,width:1344,height:768,alt:`Снегозадержатели для уже смонтированной крыши: что выбрать, если о них не подумали заранее`}},{id:`master-flesh-dlya-dymokhoda-kak-pravilno-vybrat-i-ustanovit-uplotnitel-na-krovle`,title:`Мастер-флеш для дымохода: как правильно выбрать и установить уплотнитель на кровле`,description:`Одним из самых сложных и ответственных элементов кровельной системы считается узел прохода дымохода через крышу. В этом месте необходимо обеспечить абсолютную герметичность и исключить риск возгорания.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/master-flesh-dlya-dymokhoda-kak-pravilno-vybrat-i-ustanovit-uplotnitel-na-krovle/`,sourceDate:`2025-10-15`,sourceDateLabel:`15.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/master-flesh-dlya-dymokhoda-kak-pravilno-vybrat-i-ustanovit-uplotnitel-na-krovle.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/3b5b486b454400e6.webp`,width:512,height:341,alt:`Мастер-флеш для дымохода: как правильно выбрать и установить уплотнитель на кровле`}},{id:`o-chem-rasskazyvayut-razmery-metallocherepitsy-vybor-parametry-i-osobennosti-profilya`,title:`О чем рассказывают размеры металлочерепицы: выбор, параметры и особенности профиля`,description:`Металлочерепица – это стальной лист с профилированной поверхностью, имитирующей форму керамической черепицы, и защитным полимерным покрытием`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/o-chem-rasskazyvayut-razmery-metallocherepitsy-vybor-parametry-i-osobennosti-profilya/`,sourceDate:`2025-10-10`,sourceDateLabel:`10.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/o-chem-rasskazyvayut-razmery-metallocherepitsy-vybor-parametry-i-osobennosti-profilya.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/9c5712ee2f8999fb.webp`,width:1024,height:1024,alt:`О чем рассказывают размеры металлочерепицы: выбор, параметры и особенности профиля`}},{id:`profnastil-s8-i-s20-v-chem-raznitsa-pri-vybore-materiala-dlya-zabora`,title:`Профнастил С8 и С20: в чем разница при выборе материала для забора`,description:`Профнастил марок С8 и С20 – одни из самых востребованных материалов для возведения заборов.`,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/profnastil-s8-i-s20-v-chem-raznitsa-pri-vybore-materiala-dlya-zabora/`,sourceDate:`2025-10-09`,sourceDateLabel:`09.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/profnastil-s8-i-s20-v-chem-raznitsa-pri-vybore-materiala-dlya-zabora.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/718653313226369b.webp`,width:512,height:143,alt:`Профнастил С8 и С20: в чем разница при выборе материала для забора`}},{id:`shiber-dlya-dymokhoda-chto-eto-i-zachem-on-nuzhen`,title:`Шибер для дымохода: что это и зачем он нужен`,description:`Шибер – это регулирующее устройство, применяемое в дымоходах, вентиляционных каналах и водозаборных системах для изменения площади сечения трубы.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/shiber-dlya-dymokhoda-chto-eto-i-zachem-on-nuzhen/`,sourceDate:`2025-10-07`,sourceDateLabel:`07.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/shiber-dlya-dymokhoda-chto-eto-i-zachem-on-nuzhen.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/13e375ce27c20609.webp`,width:1e3,height:1e3,alt:`Шибер для дымохода: что это и зачем он нужен`}},{id:`snegozaderzhateli-na-kryshe-zashchita-raznovidnosti-i-ustanovka`,title:`Снегозадержатели на крыше: защита, разновидности и установка`,description:``,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/snegozaderzhateli-na-kryshe-zashchita-raznovidnosti-i-ustanovka/`,sourceDate:`2025-10-02`,sourceDateLabel:`02.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/snegozaderzhateli-na-kryshe-zashchita-raznovidnosti-i-ustanovka.json`},{id:`prokhod-dymokhoda-cherez-kryshu`,title:`Проход дымохода через крышу`,description:`Вывод дымохода за пределы дома – это не просто техническая задача, а важный этап, от которого напрямую зависит безопасность жильцов, эффективность отопления и долговечность крыши.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/prokhod-dymokhoda-cherez-kryshu/`,sourceDate:`2025-10-01`,sourceDateLabel:`01.10.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/prokhod-dymokhoda-cherez-kryshu.json`},{id:`sendvich-truba-dlya-bani-osobennosti-vybora-i-pravila-ustanovki`,title:`Сэндвич труба для бани: выбор, размеры и правила монтажа дымохода`,description:`Надёжный дымоход в бане – это не просто элемент конструкции, а основа безопасной работы печи.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/sendvich-truba-dlya-bani-osobennosti-vybora-i-pravila-ustanovki/`,sourceDate:`2025-08-27`,sourceDateLabel:`27.08.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/sendvich-truba-dlya-bani-osobennosti-vybora-i-pravila-ustanovki.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/fbfc9c60e081032e.webp`,width:1536,height:1024,alt:`Сэндвич труба для бани: выбор, размеры и правила монтажа дымохода`}},{id:`gde-luchshe-ustanovit-dymokhod-stalnoy`,title:`Где лучше установить дымоход стальной: внутри или снаружи дома?`,description:`Выбор места для монтажа дымохода из нержавеющей стали — важное решение, которое влияет на безопасность, эффективность отопления и долговечность системы.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/gde-luchshe-ustanovit-dymokhod-stalnoy/`,sourceDate:`2025-06-04`,sourceDateLabel:`04.06.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/gde-luchshe-ustanovit-dymokhod-stalnoy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/97369807b9bd8a51.webp`,width:433,height:650,alt:`Где лучше установить дымоход стальной: внутри или снаружи дома?`}},{id:`kak-vybrat-dekorativnyy-metallicheskiy-shtaketnik-dlya-zabora-kharakteristiki-i-preimushchestva`,title:`Как выбрать декоративный металлический штакетник для забора: характеристики и преимущества`,description:`Современные ограждения всё чаще строятся из металлического штакетника. Этот материал зарекомендовал себя как один из самых надежных, эстетичных и простых в монтаже.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kak-vybrat-dekorativnyy-metallicheskiy-shtaketnik-dlya-zabora-kharakteristiki-i-preimushchestva/`,sourceDate:`2025-05-14`,sourceDateLabel:`14.05.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-vybrat-dekorativnyy-metallicheskiy-shtaketnik-dlya-zabora-kharakteristiki-i-preimushchestva.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/302b1738317ab503.webp`,width:560,height:374,alt:`Как выбрать декоративный металлический штакетник для забора: характеристики и преимущества`}},{id:`chto-vybrat-dlya-otdelki-fasada-vinilovyy-ili-metallicheskiy-sayding`,title:`Что выбрать для отделки фасада: виниловый или металлический сайдинг?`,description:`Сайдинг является популярным вариантом для внешней облицовки домов. Он защищает стены от влаги, ветра и температурных перепадов, а также придаёт постройке эстетичный внешний вид.`,categoryId:`sayding`,source:`https://metallik.ru/articles/sayding/chto-vybrat-dlya-otdelki-fasada-vinilovyy-ili-metallicheskiy-sayding/`,sourceDate:`2025-05-12`,sourceDateLabel:`12.05.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/chto-vybrat-dlya-otdelki-fasada-vinilovyy-ili-metallicheskiy-sayding.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/0bb0b0685449c68f.webp`,width:1024,height:1024,alt:`Что выбрать для отделки фасада: виниловый или металлический сайдинг?`}},{id:`kak-razrezat-profnastil-bez-povrezhdeniy`,title:`Как разрезать профнастил без повреждений`,description:``,categoryId:`profnastil`,source:`https://metallik.ru/articles/profnastil/kak-razrezat-profnastil-bez-povrezhdeniy/`,sourceDate:`2025-04-24`,sourceDateLabel:`24.04.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-razrezat-profnastil-bez-povrezhdeniy.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/bcb9d7469c1bcc5c.webp`,width:1280,height:720,alt:`Как разрезать профнастил без повреждений`}},{id:`kakie-klyuchevye-razmery-nuzhno-uchityvat-pri-vybore-metallicheskogo-shtaketnika`,title:`Какие ключевые размеры нужно учитывать при выборе металлического штакетника`,description:`Металлический штакетник (или евроштакетник) — это один из самых популярных вариантов для создания современных ограждений. Он имеет такие преимущества, как высокая прочность, долговечность и привлекательный внешний вид, что делает его отличной альтернативой традиционным деревянным заборам. В данной статье подробно рассмотрим, какие важные характеристики следует учитывать при выборе металлоштакетника для создания прочного и эстетичного забора, который прослужит долго.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kakie-klyuchevye-razmery-nuzhno-uchityvat-pri-vybore-metallicheskogo-shtaketnika/`,sourceDate:`2025-03-27`,sourceDateLabel:`27.03.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kakie-klyuchevye-razmery-nuzhno-uchityvat-pri-vybore-metallicheskogo-shtaketnika.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/8e46e0c30b75aca2.webp`,width:1280,height:853,alt:`Какие ключевые размеры нужно учитывать при выборе металлического штакетника`}},{id:`kak-rasschitat-evroshtaketnik-dlya-zabora`,title:`Как рассчитать евроштакетник для забора`,description:`Каждый владелец загородного дома или другой недвижимости, планируя установку ограждения, задается вопросами, как рассчитать евроштакетник для забора, сколько кубов или погонных метров нужно будет купить и как в дальнейшем все смонтировать. Знание точных параметров поможет спланировать бюджет на будущее ограждение. Специалисты компании «МЕТАЛЛИК И КО» помогут произвести расчет евроштакетника на забор быстро и грамотно.`,categoryId:`shtaketnik-metallicheskiy`,source:`https://metallik.ru/articles/shtaketnik-metallicheskiy/kak-rasschitat-evroshtaketnik-dlya-zabora/`,sourceDate:`2025-02-06`,sourceDateLabel:`06.02.2025`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-rasschitat-evroshtaketnik-dlya-zabora.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/6f9827d53123d6b9.webp`,width:1280,height:854,alt:`Как рассчитать евроштакетник для забора`}},{id:`kak-pravilno-ustanovit-snegozaderzhateli-na-kryshe`,title:`Как правильно установить снегозадержатели на крыше`,description:`Расскажем как правильно поставить снегозадержатели на разных крышах: металлочерепице и профнастиле.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/kak-pravilno-ustanovit-snegozaderzhateli-na-kryshe/`,sourceDate:`2024-11-28`,sourceDateLabel:`28.11.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-pravilno-ustanovit-snegozaderzhateli-na-kryshe.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/fbe5c6fa3647d316.webp`,width:1280,height:853,alt:`Как правильно установить снегозадержатели на крыше`}},{id:`razlichiya-v-razmerakh-i-naznachenii-listov-gipsokartona`,title:`Размеры листов гипсокартона: назначение, толщина и вес ГКЛ`,description:`Листы гипсокартона часто применяются во внутренней отделке помещений: при строительстве межкомнатных перегородок, отделке стен, потолка, дверных проемов и откосов, а также для создания объемных элементов декора и декорирования коммуникационных элементов.`,categoryId:`profil-dlya-gipsokartona`,source:`https://metallik.ru/articles/profil-dlya-gipsokartona/razlichiya-v-razmerakh-i-naznachenii-listov-gipsokartona/`,sourceDate:`2024-10-19`,sourceDateLabel:`19.10.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/razlichiya-v-razmerakh-i-naznachenii-listov-gipsokartona.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/7a4b31d896e58365.webp`,width:1600,height:1067,alt:`Размеры листов гипсокартона: назначение, толщина и вес ГКЛ`}},{id:`gidroizolyatsionnye-plenki-dlya-kryshi`,title:`Гидроизоляционная пленка на кровлю: разновидности и характеристики материалов`,description:`Виды пленок для кровли, свойства и устройство подкровельных пленок В статье от Металлик и Ко расскажем все про подкровельные пленки: виды гидроизоляции для крыши, свойства материалов и дадим рекомендации по укладке подкровельных пленок.`,categoryId:`krovlya`,source:`https://metallik.ru/articles/krovlya/gidroizolyatsionnye-plenki-dlya-kryshi/`,sourceDate:`2024-08-19`,sourceDateLabel:`19.08.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/gidroizolyatsionnye-plenki-dlya-kryshi.json`},{id:`primenenie-ograzhdeniy-zhalyuzi`,title:`Применение ограждений жалюзи`,description:`Рассказываем о широком применение ограждений жалюзи в зонировании и объектах загородного, муниципального, гражданского назначения.`,categoryId:`ograzhdeniya-zhalyuzi`,source:`https://metallik.ru/articles/ograzhdeniya-zhalyuzi/primenenie-ograzhdeniy-zhalyuzi/`,sourceDate:`2024-03-12`,sourceDateLabel:`12.03.2024`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/primenenie-ograzhdeniy-zhalyuzi.json`},{id:`kak-pochistit-dymokhod`,title:`Как почистить дымоход`,description:`Правильная и регулярная очистка дымохода является важной процедурой для обеспечения безопасности и эффективной работы камина, печи или газового котла.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/kak-pochistit-dymokhod/`,sourceDate:`2023-11-07`,sourceDateLabel:`07.11.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/kak-pochistit-dymokhod.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/2d6f15ef6f55e00b.webp`,width:437,height:311,alt:`Как почистить дымоход`}},{id:`dymokhody-termo`,title:`Дымоходы Termo`,description:`В ассортименте компании представлены интерьерные дымоходы Termo, сочетающиеся с цветом отопительного агрегата или дизайном помещения.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/dymokhody-termo/`,sourceDate:`2023-02-06`,sourceDateLabel:`06.02.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/dymokhody-termo.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/0ac67ed35f8b5d1a.webp`,width:514,height:345,alt:`Дымоходы Termo`}},{id:`sistema-podogreva-vody`,title:`Система подогрева воды`,description:`Возможность пользоваться централизованной горячей водой в бане или доме доступна не всем. Поэтому существуют различные альтернативные варианты получения горячей воды в помещении.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/sistema-podogreva-vody/`,sourceDate:`2023-01-24`,sourceDateLabel:`24.01.2023`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/sistema-podogreva-vody.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/2d7e7cd4aa2b1872.webp`,width:1172,height:826,alt:`Система подогрева воды`}},{id:`7-pravil-bezopasnoy-bani`,title:`7 правил безопасной бани`,description:`Металич уже рассказывал, что баня - один из лучших способов расслабиться и восстановить силы, поэтому построить собственную баню - отличное решение. Если вы задумались о бане, то позаботьтесь и о безопасной установке печи.`,categoryId:`dymokhody`,source:`https://metallik.ru/articles/dymokhody/7-pravil-bezopasnoy-bani/`,sourceDate:`2022-09-01`,sourceDateLabel:`01.09.2022`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/7-pravil-bezopasnoy-bani.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/30a8a6b0a1af9a0f.webp`,width:1022,height:813,alt:`7 правил безопасной бани`}},{id:`ventilyatsiya-krovli-viotto`,title:`Вентиляция кровли Viotto`,description:`Viotto - линейка доступных продуктов кровельной вентиляции созданных в России и специально для России.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/ventilyatsiya-krovli-viotto/`,sourceDate:`2021-04-21`,sourceDateLabel:`21.04.2021`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/ventilyatsiya-krovli-viotto.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/b55efc01fbe7ad97.webp`,width:1e3,height:667,alt:`Вентиляция кровли Viotto`}},{id:`elementy-bezopasnosti-krovli-borge`,title:`Элементы безопасности кровли Borge`,description:`Системы безопасности кровли и кровельные аксессуары BORGE - не просто набор элементов, а полноценная инженерная защита дома.`,categoryId:`komplektuyushchie-i-dobornye-elementy`,source:`https://metallik.ru/articles/komplektuyushchie-i-dobornye-elementy/elementy-bezopasnosti-krovli-borge/`,sourceDate:`2021-01-22`,sourceDateLabel:`22.01.2021`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/elementy-bezopasnosti-krovli-borge.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/444bde04bca71e29.webp`,width:960,height:720,alt:`Элементы безопасности кровли Borge`}},{id:`profil-dlya-gipsokartona`,title:`Профиль для гипсокартона: виды, размеры и применение`,description:`Профили для гипсокартона изготавливаются методом холодного проката с последующей оцинковкой. Получающиеся после этих манипуляций оцинкованные профили устойчивы к ржавчине за счёт защитных свойств цинка.`,categoryId:`profil-dlya-gipsokartona`,source:`https://metallik.ru/articles/profil-dlya-gipsokartona/profil-dlya-gipsokartona/`,sourceDate:`2018-09-24`,sourceDateLabel:`24.09.2018`,bodyPath:`/summary-pages/2026/2026-11/metallik-demo/data/journal/profil-dlya-gipsokartona.json`,image:{src:`/summary-pages/2026/2026-11/metallik-demo/images/journal/0b84e2b10e455152.webp`,width:242,height:134,alt:`Профиль для гипсокартона: виды, размеры и применение`}}]},t=e.articles,n=e.categories;e.source,e.checkedAt;export{n,t};